import sys, json, random, collections
sys.path.insert(0,'/workspace/dev')
import gen, difftest
stats=collections.Counter(); bad=0
def mk(rnd, variant):
    if variant==0: return gen.make_request(rnd)
    if variant==1: return gen.make_request(rnd, nrel=rnd.randint(3,5), tight=False)
    if variant==2: return gen.make_request(rnd, nrel=1, tight=True, nflows=8, nop=120)
    if variant==3:
        rels=[gen.make_release(rnd,'m0',mode='range',classes=rnd.randint(2,4),width=rnd.randint(3,6))[0]]
        return {'capacity':{'range':rnd.randint(0,2),'exact':rnd.randint(0,2)},'releases':rels,
                'blocks':gen.make_blocks(rnd,['m0'],rels,[r['id'] for r in rels] and None or None) if False else gen.make_blocks(rnd,['m0'],rels,None)}
    return gen.make_request(rnd)
for i in range(400):
    rnd=random.Random(77000+i)
    req=mk(rnd, i%4)
    ok,got,want,ge,we=difftest.run_one(req)
    if not ok:
        bad+=1
        print('MISMATCH seed',77000+i,'variant',i%4,ge,we)
        json.dump(req,open('/tmp/g_%d.json'%(77000+i),'w'))
        json.dump(got,open('/tmp/g_%d.got'%(77000+i),'w'))
        json.dump(want,open('/tmp/g_%d.want'%(77000+i),'w'))
        if bad>2: break
        continue
    if 'error' in got: stats['error']+=1; continue
    for c in got['catalog']:
        stats['frag']+=len(c['fragments']); stats['noise']+=len(c['noise'])
        stats['clusters']+=len(c['clusters']); stats['kept']+=sum(1 for x in c['clusters'] if x['kept'])
        stats['entries']+=c['entries']
        stats['border']+=sum(1 for x in c['clusters'] if len(x['members'])!=len(x['core']))
    for d in got['decisions']: stats['reason_'+d['reason']]+=1
    for ins in got['installs']: stats['install_'+ins['status']]+=1
print('mismatches',bad); print(dict(stats))
EOF
